namespace BlazorApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<NotificationItem> _allNotifications;

    public NotificationService()
    {
        _allNotifications = new List<NotificationItem>
        {
            new() { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) },
            new() { Id = _nextId++, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
            new() { Id = _nextId++, Message = "New feature available: Dark Mode.", Timestamp = DateTime.UtcNow.AddMinutes(-2) }
        };
    }

    public Task<List<NotificationItem>> GetNotificationsAsync()
    {
        return Task.FromResult(_allNotifications.ToList());
    }

    public Task<List<NotificationItem>> GetNotificationsSinceAsync(int lastId)
    {
        // Simulate new notifications arriving over time
        if (Random.Shared.NextDouble() > 0.6)
        {
            _allNotifications.Add(new NotificationItem
            {
                Id = _nextId++,
                Message = $"New event at {DateTime.UtcNow:HH:mm:ss}",
                Timestamp = DateTime.UtcNow
            });
        }

        var newer = _allNotifications.Where(n => n.Id > lastId).ToList();
        return Task.FromResult(newer);
    }
}

