@page "/notifications"
@rendermode InteractiveServer
@using BlazorApp.Services
@inject NotificationService NotificationService
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications</h1>

<span class="badge bg-primary">@Notifications.Count</span>

@if (Notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var notification in Notifications.OrderByDescending(n => n.Timestamp))
        {
            <li class="list-group-item">
                <strong>@notification.Message</strong>
                <small class="text-muted ms-2">@notification.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<NotificationItem> Notifications { get; set; } = new();

    private CancellationTokenSource? _cts;

    protected override async Task OnInitializedAsync()
    {
        // Only fetch if not restored from prerender state
        if (Notifications.Count == 0)
        {
            Notifications = await NotificationService.GetNotificationsAsync();
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender never runs during prerender — only when interactive
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(5000, cancellationToken);

                var lastId = Notifications.Count > 0 ? Notifications.Max(n => n.Id) : 0;
                var newer = await NotificationService.GetNotificationsSinceAsync(lastId);

                if (newer.Count > 0)
                {
                    Notifications.AddRange(newer);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (TaskCanceledException)
            {
                break;
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

